import React, { useState, useEffect, useCallback } from 'react';
import VeloigpMetrics from '../components/metrics/VeloigpMetrics';
import VeloigpCard from '../components/ui/VeloigpCard';
import VeloigpButton from '../components/ui/VeloigpButton';
import { 
  fetchAllReports, 
  processarDadosAPI, 
  getVeloigpLogs,
  testarConexaoAPI 
} from '../services/api55pbx-veloigp';

const VeloigpDashboard = () => {
  const [dados, setDados] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [periodo, setPeriodo] = useState('24h');
  const [logs, setLogs] = useState([]);
  const [statusAPI, setStatusAPI] = useState(null);

  // Períodos disponíveis
  const periodos = [
    { value: '1h', label: 'Última Hora' },
    { value: '24h', label: 'Últimas 24h' },
    { value: '7d', label: 'Últimos 7 dias' },
    { value: '30d', label: 'Últimos 30 dias' }
  ];

  // Buscar dados baseado no período selecionado
  useEffect(() => {
    buscarDados();
    testarConexao();
    atualizarLogs();
  }, [periodo]);

  const buscarDados = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      
      const { dataInicio, dataFim } = calcularPeriodo(periodo);
      
      const response = await fetchAllReports(dataInicio, dataFim);
      
      // Processar dados do report principal
      const dadosProcessados = processarDadosAPI(response.report01);
      setDados(dadosProcessados);
      
    } catch (err) {
      console.error('Erro ao buscar dados:', err);
      
      // Se for erro de API, tentar usar dados simulados
      if (err.message.includes('API 55PBX')) {
        try {
          const { obterDadosSimulados } = await import('../services/api55pbx-veloigp');
          const dadosSimulados = await obterDadosSimulados();
          const dadosProcessados = processarDadosAPI(dadosSimulados);
          setDados(dadosProcessados);
          setError('Usando dados simulados - API indisponível');
        } catch (simError) {
          setError('Erro ao carregar dados: ' + err.message);
        }
      } else {
        setError('Erro ao carregar dados: ' + err.message);
      }
    } finally {
      setLoading(false);
    }
  }, [periodo]);

  const calcularPeriodo = (periodoSelecionado) => {
    const agora = new Date();
    const dataFim = new Date(agora);
    const dataInicio = new Date(agora);
    
    switch (periodoSelecionado) {
      case '1h':
        dataInicio.setHours(dataInicio.getHours() - 1);
        break;
      case '24h':
        dataInicio.setDate(dataInicio.getDate() - 1);
        break;
      case '7d':
        dataInicio.setDate(dataInicio.getDate() - 7);
        break;
      case '30d':
        dataInicio.setDate(dataInicio.getDate() - 30);
        break;
      default:
        dataInicio.setDate(dataInicio.getDate() - 1);
    }
    
    return { dataInicio, dataFim };
  };

  const testarConexao = async () => {
    try {
      const resultado = await testarConexaoAPI();
      setStatusAPI(resultado);
    } catch (err) {
      setStatusAPI({
        connected: false,
        error: err.message,
        message: 'Erro ao testar conexão'
      });
    }
  };

  const atualizarLogs = () => {
    const logsAtuais = getVeloigpLogs();
    setLogs(logsAtuais);
  };

  const formatarNumero = (numero) => {
    return numero.toLocaleString('pt-BR');
  };

  const calcularVariacao = (atual, anterior) => {
    if (!anterior || anterior === 0) return 0;
    return ((atual - anterior) / anterior * 100).toFixed(1);
  };

  return (
    <div className="veloigp-dashboard">
        {/* Header do Dashboard */}
        <div className="page-header">
          <h1 className="page-title">Dashboard 55PBX</h1>
          <hr className="page-divider" />
        </div>
        
        {/* Status da API */}
        <div className="api-status-card">
          <VeloigpCard className="container-main">
            <div className="status-title-row">
              <h3 className="veloigp-card__title">Status da API</h3>
              <span className={`status-badge ${statusAPI?.connected ? 'connected' : 'disconnected'}`}>
                {statusAPI?.connected ? '🟢 Conectado' : '🔴 Desconectado'}
              </span>
            </div>
            <div className="status-content">
              {/* Controles dentro do card */}
              <div className="status-controls">
                <div className="period-selector">
                  <label htmlFor="periodo">Período:</label>
                  <select 
                    id="periodo"
                    value={periodo} 
                    onChange={(e) => setPeriodo(e.target.value)}
                    className="period-select"
                  >
                    {periodos.map(p => (
                      <option key={p.value} value={p.value}>
                        {p.label}
                      </option>
                    ))}
                  </select>
                </div>
                <VeloigpButton 
                  variant="primary" 
                  icon="fas fa-refresh"
                  onClick={buscarDados}
                  loading={loading}
                >
                  Atualizar
                </VeloigpButton>
              </div>
            </div>
          </VeloigpCard>
        </div>

        {/* Métricas Principais */}
        {dados && (
          <div className="metrics-overview">
            <div className="metrics-grid">
              <VeloigpCard
                title="Total de Chamadas"
                subtitle="Período selecionado"
                icon="fas fa-phone"
                className="container-main"
              >
                <div className="metric-display">
                  <div className="metric-number">
                    {formatarNumero(dados.totalChamadas)}
                  </div>
                  <div className="metric-trend positive">
                    <i className="fas fa-arrow-up"></i>
                    <span>+12% vs período anterior</span>
                  </div>
                </div>
              </VeloigpCard>

              <VeloigpCard
                title="Taxa de Atendimento"
                subtitle="Chamadas atendidas"
                icon="fas fa-check-circle"
                className="container-main"
              >
                <div className="metric-display">
                  <div className="metric-number">
                    {dados.taxaAtendimento}
                  </div>
                  <div className="metric-trend positive">
                    <i className="fas fa-arrow-up"></i>
                    <span>+2.1% vs período anterior</span>
                  </div>
                </div>
              </VeloigpCard>

              <VeloigpCard
                title="Tempo Médio"
                subtitle="Duração das chamadas"
                icon="fas fa-clock"
                className="container-main"
              >
                <div className="metric-display">
                  <div className="metric-number">
                    {dados.tempoMedioAtendimento}
                  </div>
                  <div className="metric-trend negative">
                    <i className="fas fa-arrow-down"></i>
                    <span>-5% vs período anterior</span>
                  </div>
                </div>
              </VeloigpCard>

              <VeloigpCard
                title="Satisfação"
                subtitle="Avaliação dos clientes"
                icon="fas fa-star"
                className="container-main"
              >
                <div className="metric-display">
                  <div className="metric-number">
                    {dados.metricas.satisfacaoGeral}
                  </div>
                  <div className="metric-trend positive">
                    <i className="fas fa-arrow-up"></i>
                    <span>+0.3 vs período anterior</span>
                  </div>
                </div>
              </VeloigpCard>
            </div>
          </div>
        )}

        {/* Componente de Métricas Detalhadas */}
        <VeloigpMetrics />

        {/* Resumo das Filas */}
        {dados && dados.filas && (
          <div className="queues-summary">
            <VeloigpCard
              title="Resumo das Filas"
              subtitle="Performance por fila"
              icon="fas fa-list"
              className="container-main"
            >
              <div className="queues-overview">
                {dados.filas.slice(0, 3).map((fila, index) => (
                  <div key={index} className="queue-summary">
                    <div className="queue-info">
                      <h4>{fila.nome}</h4>
                      <span className={`queue-status ${fila.status.toLowerCase()}`}>
                        {fila.status}
                      </span>
                    </div>
                    <div className="queue-stats">
                      <div className="stat">
                        <span className="stat-label">Atendidas:</span>
                        <span className="stat-value">{fila.atendidas}</span>
                      </div>
                      <div className="stat">
                        <span className="stat-label">Taxa:</span>
                        <span className="stat-value">{fila.taxaAtendimento}</span>
                      </div>
                      <div className="stat">
                        <span className="stat-label">Agentes:</span>
                        <span className="stat-value">{fila.agentes}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </VeloigpCard>
          </div>
        )}

        {/* Logs da API */}
        <div className="api-logs">
          <VeloigpCard
            title="Logs da API"
            subtitle="Histórico de operações"
            icon="fas fa-list-alt"
            className="container-main"
          >
            <div className="logs-content">
              <div className="logs-header">
                <VeloigpButton 
                  variant="secondary" 
                  size="small"
                  icon="fas fa-refresh"
                  onClick={atualizarLogs}
                >
                  Atualizar Logs
                </VeloigpButton>
                <span className="logs-count">
                  {logs.length} entradas
                </span>
              </div>
              <div className="logs-list">
                {logs.slice(-10).reverse().map((log, index) => (
                  <div key={index} className={`log-entry ${log.type}`}>
                    <div className="log-time">
                      {new Date(log.timestamp).toLocaleTimeString('pt-BR')}
                    </div>
                    <div className="log-message">
                      {log.message}
                    </div>
                    <div className="log-type">
                      <i className={`fas fa-${log.type === 'success' ? 'check' : log.type === 'error' ? 'times' : 'info'}`}></i>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </VeloigpCard>
        </div>

        {/* Loading State */}
        {loading && (
          <div className="dashboard-loading">
            <div className="loading-content">
              <i className="fas fa-spinner fa-spin"></i>
              <p>Carregando dados...</p>
            </div>
          </div>
        )}

        {/* Error State */}
        {error && (
          <div className="dashboard-error">
            <VeloigpCard
              title="Erro ao Carregar Dados"
              subtitle="Não foi possível conectar com a API"
              icon="fas fa-exclamation-triangle"
              className="container-main"
            >
              <p>{error}</p>
              <VeloigpButton 
                variant="primary" 
                icon="fas fa-refresh"
                onClick={buscarDados}
              >
                Tentar Novamente
              </VeloigpButton>
            </VeloigpCard>
          </div>
        )}
    </div>
  );
};

export default VeloigpDashboard;
